# Initially generated by GitHub Copilot.
"""Split cam1753 two-page spread images into individual page images.

Uses the column-mean brightness profile to find the gutter (darkest
vertical stripe in the central 20% of the image), then splits there.

Naming convention (see cam1753-spreads-provenance.md):
  archive page 0077  →  right half = 0072B,  left half = 0073A
  i.e. left_leaf = archive_page − 4;  right_leaf = left_leaf − 1

Produces per-spread documentation JSON files in cam1753-spread-splits-doc/
recording the detected gutter position, spread dimensions, and output page
names so the split can be reproduced or audited without re-running the
gutter finder.
"""

import json
import os
import numpy as np
from PIL import Image

import cam1753_paths

# EXIF tag number for ImageDescription
_EXIF_IMAGE_DESCRIPTION = 0x010E

# Offset: archive page number minus left-page leaf number
ARCHIVE_TO_LEFT_LEAF_OFFSET = 4


def find_gutter(img_gray):
    """Return the x-coordinate of the gutter (darkest column in central 20%)."""
    arr = np.array(img_gray, dtype=np.float64)
    profile = arr.mean(axis=0)
    w = arr.shape[1]
    lo = int(w * 0.4)
    hi = int(w * 0.6)
    return lo + int(np.argmin(profile[lo:hi]))


def _make_exif(description_str):
    """Return EXIF bytes with ImageDescription set to the given string."""
    exif = Image.Exif()
    exif[_EXIF_IMAGE_DESCRIPTION] = description_str
    return exif.tobytes()


def main():
    """Split every downloaded spread into two page images, and document each split.

    Rewrites all 28 ``cam1753-pages/*.jpg`` and all 15
    ``cam1753-spread-splits-doc/*.json``, which together are 43 of the 45 tracked
    artifacts this repo's code can regenerate.

    WHY THIS FILE HAS A ``main()`` NOW.  Everything below ran at MODULE SCOPE in
    codex-index-cam1753 -- the two ``os.makedirs``, the loop over fourteen spreads,
    the 28 image writes -- with no ``main()`` and no ``if __name__`` guard, until
    Phase 3 of ``doc/PLAN-evacuate-python-from-codex-index-trio.md`` on 2026-08-22.
    Harmless in a repo whose only entry into it was to run it; not harmless in
    MAM-basics, where importing a top-level module to inspect it is ordinary and
    would have rewritten 43 tracked files.
    """
    spread_dir = cam1753_paths.spreads_dir()
    out_dir = cam1753_paths.pages_dir()
    doc_dir = cam1753_paths.spread_splits_doc_dir()
    os.makedirs(out_dir, exist_ok=True)
    os.makedirs(doc_dir, exist_ok=True)

    files = sorted(f for f in os.listdir(spread_dir) if f.endswith(".jpg"))
    all_splits = []

    for fname in files:
        # Extract archive page number from filename like "cam1753-page-0077.jpg"
        archive_page = int(fname.split("-")[-1].split(".")[0])
        left_leaf = archive_page - ARCHIVE_TO_LEFT_LEAF_OFFSET
        right_leaf = left_leaf - 1

        img = Image.open(os.path.join(spread_dir, fname))
        gray = img.convert("L")
        gutter_x = find_gutter(gray)

        # Left side of image = recto (A) of left_leaf
        left_half = img.crop((0, 0, gutter_x, img.height))
        left_name = f"{left_leaf:04d}A.jpg"

        # Right side of image = verso (B) of right_leaf
        right_half = img.crop((gutter_x, 0, img.width, img.height))
        right_name = f"{right_leaf:04d}B.jpg"

        left_path = os.path.join(out_dir, left_name)
        right_path = os.path.join(out_dir, right_name)

        # Build per-page EXIF metadata describing the split provenance
        left_meta = json.dumps(
            {
                "source_spread": fname,
                "archive_page": archive_page,
                "spread_width": img.width,
                "spread_height": img.height,
                "gutter_x": gutter_x,
                "crop": "left",
                "crop_box": [0, 0, gutter_x, img.height],
            }
        )
        right_meta = json.dumps(
            {
                "source_spread": fname,
                "archive_page": archive_page,
                "spread_width": img.width,
                "spread_height": img.height,
                "gutter_x": gutter_x,
                "crop": "right",
                "crop_box": [gutter_x, 0, img.width, img.height],
            }
        )

        left_half.save(left_path, quality=95, exif=_make_exif(left_meta))
        right_half.save(right_path, quality=95, exif=_make_exif(right_meta))

        # Record split documentation
        split_record = {
            "spread_file": fname,
            "archive_page": archive_page,
            "spread_width": img.width,
            "spread_height": img.height,
            "gutter_x": gutter_x,
            "left_page": {
                "file": left_name,
                "leaf": left_leaf,
                "side": "A",
                "width": left_half.size[0],
                "height": left_half.size[1],
            },
            "right_page": {
                "file": right_name,
                "leaf": right_leaf,
                "side": "B",
                "width": right_half.size[0],
                "height": right_half.size[1],
            },
        }
        all_splits.append(split_record)

        # Write per-spread JSON
        doc_path = os.path.join(doc_dir, fname.replace(".jpg", ".json"))
        with open(doc_path, "w", encoding="utf-8", newline="") as f:
            json.dump(split_record, f, indent=2, ensure_ascii=False)
            f.write("\n")

        print(
            f"{fname}  gutter@{gutter_x}  ->  {left_name} ({left_half.size[0]}x{left_half.size[1]})"
            f"  +  {right_name} ({right_half.size[0]}x{right_half.size[1]})"
        )

    # Write combined summary
    summary_path = os.path.join(doc_dir, "_all-splits.json")
    with open(summary_path, "w", encoding="utf-8", newline="") as f:
        json.dump(all_splits, f, indent=2, ensure_ascii=False)
        f.write("\n")

    print(f"\nDone. {len(files)} spreads -> {len(files) * 2} pages in {out_dir}/")
    print(
        f"Split docs written to {doc_dir}/ ({len(all_splits)} per-spread + 1 summary)"
    )
